xml.Script:
        clYellow  := 'FFFF00';
        clBlue    := '0000A0';
        clOrange  := 'FF6000';
        clRed     := 'FF0000';
        clGreen   := '008000';
        clViolett := '800080';

        R := 0.9;
        H1 := R * ( 3 * sqrt(5) + 15) / 40;
        H2 := R * (-3 * sqrt(5) +  9) /  8;
        dZ := R * (-1 * sqrt(5) +  3) /  8;

        for i := 0 to 2 do begin
            x[i] := R * sin(2 * Pi / 3 * i);
            y[i] := R * cos(2 * Pi / 3 * i);
        end;

        // Calcs normal to plane with 3 points
        procedure Normal(x1, y1, z1, x2, y2, z2, x3, y3, z3, i);
        begin
          px[i] := (y1-y3) * (z2-z3) - (y2-y3) * (z1-z3);
          py[i] := (z1-z3) * (x2-x3) - (z2-z3) * (x1-x3);
          pz[i] := (x1-x3) * (y2-y3) - (x2-x3) * (y1-y3);
        end;

        // Calc all Normal and fill array
        Normal( x[1],y[1],dZ, x[0],y[0],dZ, 0,0,-H2, 0); // " 0;1;4"
        Normal( x[2],y[2],dZ, x[1],y[1],dZ, 0,0,-H2, 1); // " 1;2;4"
        Normal( x[0],y[0],dZ, x[2],y[2],dZ, 0,0,-H2, 2); // " 2;0;4"

        A1 := 2*Pi/5;

        D := R * (29 * sqrt(5) - 48) / 74;
